package com.salespunch360.mobile.ui.account.purchase
import androidx.compose.foundation.layout.*;import androidx.compose.foundation.lazy.LazyColumn;import androidx.compose.foundation.lazy.items;import androidx.compose.material3.*;import androidx.compose.runtime.Composable;import androidx.compose.ui.Modifier;import androidx.compose.ui.text.font.FontWeight;import com.salespunch360.mobile.account.array;import com.salespunch360.mobile.account.str;import kotlinx.serialization.json.JsonObject
@Composable fun PurchaseDetail(d:JsonObject,saving:Boolean,onClose:()->Unit,onPost:(String)->Unit){AlertDialog(onDismissRequest=onClose,title={Text(d.str("documentNumber"))},confirmButton={if(d.str("status")=="DRAFT"&&d.str("type") in listOf("PURCHASE_BILL","DEBIT_NOTE"))Button(enabled=!saving,onClick={onPost(d.str("id"))}){Text("Post")}},dismissButton={TextButton(onClose){Text("Close")}},text={LazyColumn{item{Text("${d.str("type").replace('_',' ')} · ${d.str("status")}",fontWeight=FontWeight.Bold);Text(d.str("partyName"))};items(d.array("lines")){l->ListItem(headlineContent={Text(l.str("itemName"))},supportingContent={Text("${l.str("quantity")} × ₹${l.str("rate")}")},trailingContent={Text("₹${l.str("lineTotal")}")})};item{HorizontalDivider();Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("Grand total",fontWeight=FontWeight.Bold);Text("₹${d.str("grandTotal")}",fontWeight=FontWeight.Bold)};Text("Tax ₹${d.str("taxTotal")} · Payable ₹${d.str("payableAmount")}")}}})}
